from pathlib import Path
import subprocess,json,base64,hashlib
root=Path('/tmp/viewflow-windows-isolated-root.txt').read_text().strip()
s=r'''$r='__ROOT__';$s=Get-CimInstance Win32_Service -Filter "Name='ESRV_SVC_QUEENCREEK'";$p=Get-Process -Id $s.ProcessId;$owned=@(Get-CimInstance Win32_Process|Where-Object {$_.ExecutablePath -and $_.ExecutablePath.StartsWith($r,[StringComparison]::OrdinalIgnoreCase)});$tasks=@(Get-ScheduledTask -TaskName 'ViewflowPerf-IntegratedReceiver','ViewflowPerf-RestoreCodecSplit','ViewflowPerf-FrameObserver' -ErrorAction SilentlyContinue);@{time=(Get-Date).ToString('o');process_id=$p.Id;priority=$p.PriorityClass.ToString();threads=@($p.Threads|Where-Object PriorityLevel -eq 'TimeCritical'|Select-Object Id,PriorityLevel,BasePriority);service_state=$s.State;service_start=$s.StartMode;owned_processes=$owned.Count;owned_tasks=$tasks.Count;hashes=@(Get-FileHash ($r+'\native-build\Release\viewflow_windows_composition_preview.exe'),($r+'\target\release\vf-media-peer.exe'),($r+'\target\release\vf_media_peer.pdb'),($r+'\before-av1-window-peer.pdb'),($r+'\vf-media-peer-av1.exe'),($r+'\native-av1-build\Release\viewflow_windows_composition_preview.exe'),($r+'\native-build\Release\viewflow_windows_frame_observer.exe'),($r+'\isolated-receive.json'),($r+'\crates\viewflowd\src\atlas_peer.rs'),($r+'\crates\viewflowd\src\atlas_presenter_child.rs'),($r+'\crates\viewflowd\src\atlas_receiver_presenter.rs')|Select-Object Path,Hash)}|ConvertTo-Json -Depth 4'''.replace('__ROOT__',root)
r=subprocess.run(['ssh','-o','BatchMode=yes','wilf@172.16.105.70','powershell','-NoProfile','-EncodedCommand',base64.b64encode(s.encode('utf-16le')).decode()],capture_output=True,timeout=30);r.check_returncode();v=json.loads(r.stdout);Path('/tmp/viewflow-codec-final-state.json').write_text(json.dumps(v,indent=2)+'\n');assert v['owned_processes']==v['owned_tasks']==0 and v['priority']=='High' and v['service_state']=='Running' and v['service_start']=='Auto';h=v['hashes'];b=json.loads(Path('/tmp/viewflow-av1-window-binaries.json').read_text(encoding='utf-8-sig'));assert h[0]['Hash']==b['native_original'] and h[1]['Hash']==b['before'] and h[2]['Hash']==h[3]['Hash'] and h[4]['Hash']==b['candidate'] and h[5]['Hash']==b['native_av1'];assert h[7]['Hash'].lower()==hashlib.sha256(Path('/tmp/viewflow-codec-restore-receive-remote.json').read_bytes()).hexdigest()
for i,n in enumerate(['atlas_peer.rs','atlas_presenter_child.rs','atlas_receiver_presenter.rs']):assert h[8+i]['Hash'].lower()==hashlib.sha256(Path('crates/viewflowd/src/'+n).read_bytes()).hexdigest()
for n in ['send','receive']:assert Path('/tmp/viewflow-integrated-pair/'+n+'.json').read_bytes()==Path('/tmp/viewflow-codec-restore-'+n+'.json').read_bytes()
print('final binaries, sources, configs and cleanup verified',v['process_id'],v['priority'],len(v['threads']))
